/**
 * Unit tests for org.apache.commons.math3.fraction.Fraction#percentageValue()
 */
public class Fraction_percentageValue_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testPercentageValue_withPositiveFraction() {
        // Fraction(1, 2) -> 0.5. 0.5 * 100 = 50.0
        Fraction fraction = new Fraction(1, 2);
        double expected = 50.0;
        assertEquals(expected, fraction.percentageValue(), DELTA);
    }










}

